import Foundation
@testable import Rostrum
struct Row: Codable {
 let name: String
 let cells: Int
 let nonnilBorders: Int
 let sharedBorderEncounters: Int
 let unsharedBorderEncounters: Int
 let distinctAdmittedBorderIdentities: Int
 let sourceUnchanged: Bool
}
var rows: [Row] = []
for input in CommandLine.arguments.dropFirst() {
 let path = URL(fileURLWithPath: input)
 let deck = try Presentation(data: Data(contentsOf: path))
 let before = try deck.serializedData()
 let table = (try deck.slides[0].shapes.first { $0 is TableFrame } as! TableFrame).table
 var session = TableStyleResolver.RenderSession(TableStyleResolver(table: table, theme: deck.theme))
 var shared = 0, unshared = 0
 var ids = Set<ObjectIdentifier>()
 for row in 0..<table.rowCount { for column in 0..<table.columnCount {
  let effective = session.effective(row: row, column: column)
  for edge in TableCellBorder.allCases {
   guard let line = effective.properties.firstChild(named: edge.rawValue) else { continue }
   if session.ownsSharedBorder(line) { shared += 1; ids.insert(ObjectIdentifier(line)) }
   else { unshared += 1 }
  }
 } }
 let name = path.deletingPathExtension().lastPathComponent
 if name.hasPrefix("budget-near") { precondition(shared > 0 && unshared > 0) }
 if name.hasPrefix("oversize") || name.hasPrefix("direct-unique") { precondition(shared == 0 && unshared > 0) }
 let after = try deck.serializedData(); precondition(after == before)
 rows.append(Row(name: name, cells: table.rowCount * table.columnCount, nonnilBorders: shared + unshared, sharedBorderEncounters: shared, unsharedBorderEncounters: unshared, distinctAdmittedBorderIdentities: ids.count, sourceUnchanged: true))
}
let encoder = JSONEncoder(); encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
FileHandle.standardOutput.write(try encoder.encode(rows))

